create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'cashier' check(role in('owner','admin','cashier','inventory')),created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text default 'Water',unit text default 'container',stock numeric not null default 0,reorder_level numeric not null default 5,price numeric(12,2) not null default 0,active boolean default true,created_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),name text not null,contact text,address text,balance numeric(12,2) not null default 0,created_at timestamptz default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id),customer_id uuid references customers(id),qty numeric not null check(qty>0),unit_price numeric(12,2) not null,total numeric(12,2) not null,payment_method text default 'Cash',notes text,sold_at timestamptz default now(),cashier_id uuid references auth.users(id),voided boolean default false);
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),expense_date date default current_date,category text,description text,amount numeric(12,2) not null check(amount>=0),created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.settings(id boolean primary key default true,business_name text default 'Aquenza Water Refilling Station',address text,contact text,currency text default 'PHP');
create table if not exists public.audit_log(id bigint generated always as identity primary key,user_id uuid references auth.users(id),action text not null,entity text,entity_id uuid,details jsonb,created_at timestamptz default now());
insert into public.settings default values on conflict do nothing;
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.customers enable row level security;alter table public.sales enable row level security;alter table public.expenses enable row level security;alter table public.settings enable row level security;alter table public.audit_log enable row level security;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid());$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in('owner','admin'));$$;
create policy "profiles select" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "products select" on public.products for select using(public.is_staff());
create policy "products write" on public.products for all using(public.is_admin() or exists(select 1 from profiles where id=auth.uid() and role='inventory')) with check(public.is_admin() or exists(select 1 from profiles where id=auth.uid() and role='inventory'));
create policy "customers all" on public.customers for all using(public.is_staff()) with check(public.is_staff());
create policy "sales select" on public.sales for select using(public.is_staff());
create policy "expenses all" on public.expenses for all using(public.is_admin()) with check(public.is_admin());
create policy "settings select" on public.settings for select using(public.is_staff());
create policy "settings update" on public.settings for update using(public.is_admin()) with check(public.is_admin());
create policy "audit select" on public.audit_log for select using(public.is_admin());
create or replace function public.record_sale(p_product_id uuid,p_qty numeric,p_customer_id uuid,p_payment_method text,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$declare p products; sid uuid;begin select * into p from products where id=p_product_id and active=true for update;if not found then raise exception 'Product not found';end if;if p.stock<p_qty then raise exception 'Insufficient stock';end if;update products set stock=stock-p_qty where id=p_product_id;insert into sales(product_id,customer_id,qty,unit_price,total,payment_method,notes,cashier_id) values(p_product_id,p_customer_id,p_qty,p.price,p_qty*p.price,p_payment_method,p_notes,auth.uid()) returning id into sid;insert into audit_log(user_id,action,entity,entity_id,details) values(auth.uid(),'SALE_CREATED','sales',sid,jsonb_build_object('qty',p_qty,'product',p.name));return sid;end$$;
create or replace function public.void_sale(p_sale_id uuid) returns boolean language plpgsql security definer set search_path=public as $$declare s sales;begin if not public.is_admin() then raise exception 'Only admin/owner can void sales';end if;select * into s from sales where id=p_sale_id for update;if not found or s.voided then raise exception 'Sale not found or already voided';end if;update products set stock=stock+s.qty where id=s.product_id;update sales set voided=true where id=p_sale_id;insert into audit_log(user_id,action,entity,entity_id) values(auth.uid(),'SALE_VOIDED','sales',p_sale_id);return true;end$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'cashier');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.products(name,category,unit,stock,reorder_level,price) values('Purified Water - 5 Gallon','Water','container',50,10,40),('Mineral Water - 5 Gallon','Water','container',40,10,35),('Alkaline Water - 5 Gallon','Water','container',30,8,50),('Empty 5 Gallon Container','Container','piece',20,5,120) on conflict do nothing;